CREATE TABLE student(id INT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE);
CREATE TABLE bus_pass(pass_id VARCHAR(30) PRIMARY KEY,reg_no VARCHAR(30) NOT NULL,name VARCHAR(120) NOT NULL,route_no INT NOT NULL,amount DECIMAL(10,2) NOT NULL CHECK(amount>=0));
CREATE TABLE wallet(id INT PRIMARY KEY,balance DECIMAL(12,2) NOT NULL CHECK(balance>=0));
CREATE TABLE registrations(id BIGINT PRIMARY KEY AUTO_INCREMENT,student_id VARCHAR(30) NOT NULL,event_name VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_student_event(student_id,event_name));
